def find_reordering(n, a):
    total_sum = sum(a)

    # If the total sum is odd, it's impossible to split into two equal halves
    if total_sum % 2 != 0:
        return "-1"

    target_sum = total_sum // 2

    # Check if there exists a subset with sum equal to target_sum
    def can_partition(nums, target):
        dp = [False] * (target + 1)
        dp[0] = True

        for num in nums:
            for j in range(target, num - 1, -1):
                dp[j] = dp[j] or dp[j - num]

        return dp[target]

    if not can_partition(a, target_sum):
        return "-1"

    # Find one such subset
    def find_subset(nums, target):
        dp = [[False] * (target + 1) for _ in range(len(nums) + 1)]
        dp[0][0] = True

        for i in range(1, len(nums) + 1):
            for j in range(target + 1):
                if j < nums[i - 1]:
                    dp[i][j] = dp[i - 1][j]
                else:
                    dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]

        if not dp[-1][-1]:
            return []

        subset = []
        i, j = len(nums), target
        while i > 0 and j > 0:
            if dp[i - 1][j]:
                i -= 1
            else:
                subset.append(nums[i - 1])
                j -= nums[i - 1]
                i -= 1

        return subset

    subset = find_subset(a, target_sum)
    remaining = [x for x in a if x not in subset]

    return " ".join(map(str, subset + remaining))

